import { getPronunciation } from './pronunciation.mjs?v=3';
const $=s=>document.querySelector(s), app=$('#app');
const seeds=[['serendipity','뜻밖의 행운'],['embrace','받아들이다; 포용하다'],['resilience','회복력'],['make a difference','변화를 가져오다; 차이를 만들다'],['a piece of cake','아주 쉬운 일; 식은 죽 먹기'],['take it easy','마음을 편히 가지다; 쉬엄쉬엄 하다'],['curiosity','호기심'],['bloom','꽃이 피다'],['keep in mind','명심하다'],['on the same page','생각이 같다; 의견이 일치하다'],['gratitude','감사'],['step by step','차근차근; 한 걸음씩']].map(([en,ko],i)=>({id:'seed'+i,en,ko,kind:en.includes(' ')?'idiom':'word'}));
let storageOK=true;function read(k,f){try{const v=localStorage.getItem(k);return v?JSON.parse(v):f}catch{return f}}let words=read('wg-words',seeds),history=read('wg-history',[]);if(!Array.isArray(words))words=seeds;if(!Array.isArray(history))history=[];
let page='dictionary',filter='all',query='',mode=0,editing=null,session=null;
const titles=['영어 전체 쓰기','빈칸 채우기','한글 뜻 쓰기'];
const descriptions=['한글 뜻을 보고 영어 단어와 숙어를 직접 써 보세요.','한글 뜻과 일부 알파벳을 보고 빈칸을 완성하세요.','영어 표현을 보고 기억나는 한글 뜻을 써 보세요.'];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function persist(){try{localStorage.setItem('wg-words',JSON.stringify(words));localStorage.setItem('wg-history',JSON.stringify(history));storageOK=true}catch{storageOK=false;toast('저장 공간에 접근할 수 없어 새로고침하면 변경사항이 사라질 수 있습니다.')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function footer(){return `<footer><span>✳ word garden · 매일 조금씩, 더 넓은 세상으로</span><span>PROTOTYPE 01</span></footer>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='dictionary')dictionary();else if(page==='quiz')session?test():quiz();else records();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});

function pronunciationHTML(en){return '<div class="pronunciation" data-pronunciation="'+esc(en)+'"><span class="pronunciation-label">참고 발음 · 자동 생성</span><span class="pronunciation-text" lang="ko" aria-live="polite">발음 표기 준비 중…</span></div>'}
async function hydratePronunciations(root=document){
 const nodes=[...root.querySelectorAll('[data-pronunciation]')];
 await Promise.allSettled(nodes.map(async node=>{
 const term=node.dataset.pronunciation,output=node.querySelector('.pronunciation-text');
 try{const result=await getPronunciation(term);if(!node.isConnected||node.dataset.pronunciation!==term)return;output.textContent=result?.hangul||'이 표현은 한글 표기를 지원하지 않아요.';node.title='미국 영어 기준의 자동 참고 표기입니다. 실제 듣기 음성·연음·문맥에 따라 다를 수 있습니다.';}
 catch{if(node.isConnected)output.textContent='한글 표기를 불러오지 못했어요. 화면을 새로고침해 주세요.';}
 }));
}
let previewTimer;
function updatePronunciationPreview(){
 clearTimeout(previewTimer);
 const preview=$('#pronunciation-preview'),en=$('#english').value.trim();
 preview.innerHTML=en?pronunciationHTML(en):'<span class="muted">영어를 입력하면 한글 참고 발음이 자동으로 표시됩니다.</span>';
 if(en)previewTimer=setTimeout(()=>hydratePronunciations(preview),300);
}

function dictionary(){const w=words.filter(x=>(filter==='all'||x.kind===filter)&&(x.en.toLowerCase().includes(query.toLowerCase())||x.ko.includes(query)));app.innerHTML=`<section class="hero"><div><div class="eyebrow">A LITTLE EVERY DAY, A WORLD OF WORDS.</div><h1>오늘 심은 단어 하나,<br>내일의 나를 자라게 해요.</h1><p>기억하고 싶은 단어와 숙어를 모으고,<br>나만의 속도로 영어를 익혀 보세요.</p></div><div class="botanic" aria-hidden="true"><div class="leaf"></div><span>LET YOUR WORDS GROW ↗</span></div></section><section class="stats"><div class="stat"><div><label>나의 표현</label><strong>${words.length} <span class="muted">개</span></strong></div><i>✳</i></div><div class="stat"><div><label>완료한 테스트</label><strong>${history.length} <span class="muted">회</span></strong></div><i>✓</i></div><div class="stat"><div><label>평균 정답률</label><strong>${history.length?Math.round(history.reduce((s,h)=>s+h.score/h.total*100,0)/history.length):0}<span class="muted"> %</span></strong></div><i>↗</i></div></section><div class="section-head"><div><h2>나의 사전 <span class="muted">${words.length}</span></h2><span class="muted">기억하고 싶은 표현들이 자라는 곳</span></div><button class="primary" id="add">＋ 표현 추가</button></div><div class="toolbar"><div class="filters">${[['all','전체'],['word','단어'],['idiom','숙어']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'selected':''}">${t}</button>`).join('')}</div><input id="search" aria-label="단어 또는 뜻 검색" placeholder="⌕  단어 또는 뜻 검색" value="${esc(query)}"></div><div class="grid">${w.map(x=>`<article class="card"><span class="badge ${x.kind}">${x.kind==='word'?'단어 · WORD':'숙어 · IDIOM'}</span><button class="sound" data-speak="${esc(x.id)}" aria-label="${esc(x.en)} 발음 듣기">♫</button><div class="word" lang="en">${esc(x.en)}</div>${pronunciationHTML(x.en)}<div class="meaning">${esc(x.ko)}</div><div class="card-footer"><button class="text-button" data-edit="${esc(x.id)}">수정</button><button class="text-button" data-delete="${esc(x.id)}">삭제</button></div></article>`).join('')||'<div class="empty">아직 표현이 없어요. 새로운 표현을 심어 보세요.</div>'}</div><p class="bottom-note">한글 표기는 미국 영어 기준의 학습 보조용입니다. 실제 듣기와 다를 수 있어요.<br>♫ 버튼으로 소리를 확인하세요 · 데이터는 현재 브라우저에 저장됩니다${words.some(x=>x.id.startsWith('seed'))?' · 예시 단어 포함':''}</p>${footer()}`;
hydratePronunciations(app);$('#add').onclick=()=>openEditor();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;dictionary()});$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;dictionary();$('#search').focus();$('#search').setSelectionRange(pos,pos)};document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(words.find(x=>x.id===b.dataset.speak).en));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const x=words.find(x=>x.id===b.dataset.delete);if(confirm(`“${x.en}”을 삭제할까요?`)){words=words.filter(w=>w.id!==x.id);persist();dictionary();toast('표현을 삭제했습니다.')}});}
function speak(text){if(!('speechSynthesis'in window)){toast('이 브라우저는 음성 재생을 지원하지 않습니다.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.85;u.voice=speechSynthesis.getVoices().find(v=>v.lang==='en-US')||speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'))||null;u.onerror=()=>toast('영어 음성을 재생할 수 없습니다. 기기의 영어 음성 설정을 확인해 주세요.');speechSynthesis.speak(u)}
if('speechSynthesis'in window)speechSynthesis.getVoices();
function openEditor(id){editing=id||null;const w=words.find(x=>x.id===id);$('#form-title').textContent=w?'표현 수정하기':'새로운 표현 심기';$('#english').value=w?.en||'';$('#korean').value=w?.ko||'';$('#kind').value=w?.kind||'word';updatePronunciationPreview();$('#editor').showModal();$('#english').focus()}
$('#english').addEventListener('input',updatePronunciationPreview);
$('#editor').addEventListener('close',()=>{clearTimeout(previewTimer);$('#pronunciation-preview').innerHTML='';});
$('#cancel').onclick=()=>$('#editor').close();$('#word-form').onsubmit=e=>{e.preventDefault();const en=$('#english').value.trim().replace(/\s+/g,' '),ko=$('#korean').value.trim();if(!en||!ko||!ko.split(';').some(x=>x.trim()))return toast('영어와 한글 뜻을 입력해 주세요.');if(words.some(x=>x.id!==editing&&x.en.toLowerCase()===en.toLowerCase()))return toast('이미 등록한 표현입니다. 기존 표현을 수정해 주세요.');const x={id:editing||crypto.randomUUID(),en,ko,kind:$('#kind').value};if(editing)words=words.map(w=>w.id===editing?x:w);else words.unshift(x);persist();$('#editor').close();dictionary();toast(storageOK?'표현을 저장했습니다.':'현재 화면에만 반영했습니다. 저장 공간을 확인해 주세요.')};
function quiz(){app.innerHTML=`<div class="quiz-intro"><div class="eyebrow">TIME TO BLOOM</div><h1>기억을 꺼내는 작은 연습</h1><p class="muted">나의 사전에서 중복 없이 무작위 10문항을 골라요.<br>10개 미만이면 등록한 표현 전체로 진행합니다.</p></div><div class="modes">${titles.map((t,i)=>`<button class="mode ${mode===i?'selected':''}" data-mode="${i}"><b>0${i+1}</b><strong>${t}</strong><p>${descriptions[i]}</p><span class="muted">${['사과 → apple','사과 → a _ p _ e','apple → 사과'][i]}</span></button>`).join('')}</div><div class="center"><button class="primary" id="start" ${words.length?'':'disabled'}>${Math.min(10,words.length)}문항 테스트 시작하기 →</button><p class="muted">영어 대소문자는 구분하지 않아요. 한글 뜻은 등록한 뜻 중 하나와 일치하면 정답이에요.</p></div>${footer()}`;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=Number(b.dataset.mode);quiz()});$('#start').onclick=()=>{if(!words.length)return;const pool=words.map(w=>({...w}));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}session={mode,questions:pool.slice(0,10).map(w=>{const letters=[...w.en].map((c,i)=>/[a-z]/i.test(c)?i:-1).filter(i=>i>=0);let hidden=letters.filter((_,i)=>i%2===1);if(!hidden.length)hidden=letters;return {...w,hidden}}),index:0,answers:[],checked:false};test()};}
const norm=s=>s.normalize('NFKC').toLowerCase().trim().replace(/[’‘]/g,"'").replace(/\s+/g,' ');
function letterBoxes(w,mode){
 let position=0;
 return '<div class="letter-answer" role="group" aria-label="숙어 알파벳 입력">'+w.en.split(/(\s+)/).map(part=>{
 if(/^\s+$/.test(part)){position += [...part].length;return ''}
 return '<span class="letter-word">'+[...part].map(c=>{
 const i=position++,letter=/[a-z]/i.test(c),editable=letter&&(mode===0||w.hidden.includes(i));
 return editable?'<input class="letter-cell" data-position="'+i+'" aria-label="'+(i+1)+'번째 글자" required maxlength="1" pattern="[A-Za-z]" inputmode="text" autocomplete="off" autocapitalize="off" spellcheck="false">':'<span class="'+(letter?'letter-given':'letter-punctuation')+'">'+esc(c)+'</span>';
 }).join('')+'</span>';
 }).join('')+'</div>';
}
function bindLetterBoxes(){
 const cells=[...document.querySelectorAll('.letter-cell')];
 cells.forEach((cell,i)=>{
 cell.onfocus=()=>cell.select();
 cell.oninput=e=>{if(e.isComposing)return;cell.value=cell.value.replace(/[^a-z]/gi,'').slice(-1);if(cell.value&&i<cells.length-1)cells[i+1].focus()};
 cell.onpaste=e=>{e.preventDefault();const letters=e.clipboardData.getData('text').replace(/[^a-z]/gi,'');if(!letters)return;[...letters].slice(0,cells.length-i).forEach((c,j)=>cells[i+j].value=c);cells[Math.min(i+letters.length,cells.length-1)].focus()};
 cell.onkeydown=e=>{if(e.key==='Backspace'&&!cell.value&&i>0){e.preventDefault();cells[i-1].value='';cells[i-1].focus()}else if(e.key==='ArrowLeft'&&i>0){e.preventDefault();cells[i-1].focus()}else if(e.key==='ArrowRight'&&i<cells.length-1){e.preventDefault();cells[i+1].focus()}else if(e.key===' '){e.preventDefault()}};
 });
 cells[0]?.focus();
}
function test(){const s=session;if(s.index===s.questions.length){result();return}const w=s.questions[s.index],boxed=w.kind==='idiom'&&s.mode!==2,masked=[...w.en].map((c,i)=>w.hidden.includes(i)?'_':c).join('');app.innerHTML=`<div class="test"><div class="section-head"><span class="eyebrow">${titles[s.mode]}</span><button class="text-button" id="quit">테스트 종료</button></div><span class="muted">QUESTION ${s.index+1} / ${s.questions.length}</span><div class="progress"><div style="width:${s.index/s.questions.length*100}%"></div></div><p class="center muted">${s.mode===2?'다음 표현의 한글 뜻을 입력하세요':'다음 뜻에 맞는 영어 표현을 입력하세요'}</p><div class="question">${esc(s.mode===2?w.en:w.ko)}</div>${!boxed&&s.mode===1?`<div class="question" lang="en" style="letter-spacing:5px">${esc(masked)}</div><p class="muted center">빈칸의 알파벳 ${w.hidden.length}개만 순서대로 입력하세요.</p>`:''}<form id="answer-form">${boxed?letterBoxes(w,s.mode):`<input id="answer" required autocomplete="off" ${s.mode!==2?'autocapitalize="off" spellcheck="false"':''} aria-label="정답" placeholder="${s.mode===2?'한글 뜻을 입력하세요':s.mode===1?'빠진 알파벳만 입력하세요':'영어 표현을 입력하세요'}">`}${boxed?'<p class="muted center">한 칸에 알파벳 하나씩 입력하세요. 띄어쓰기는 넓은 간격으로 표시됩니다.</p>':''}<div id="feedback" aria-live="polite"></div><div class="actions"><button class="primary" id="check">정답 확인 →</button></div></form></div>`;if(boxed)bindLetterBoxes();else $('#answer').focus();$('#quit').onclick=()=>{if(confirm('진행 중인 테스트를 종료할까요? 기록은 저장되지 않습니다.')){session=null;quiz()}};$('#answer-form').onsubmit=e=>{e.preventDefault();if(s.checked){s.index++;s.checked=false;test();return}const cells=[...document.querySelectorAll('.letter-cell')];const raw=boxed?(s.mode===1?cells.map(c=>c.value).join(''):[...w.en].map((c,i)=>cells.find(cell=>Number(cell.dataset.position)===i)?.value??c).join('')):$('#answer').value;if(!raw.trim())return;const target=s.mode===1?w.hidden.map(i=>[...w.en][i]).join(''):w.en;const ok=s.mode===2?w.ko.split(';').some(k=>norm(k).replace(/\s/g,'')===norm(raw).replace(/\s/g,'')):s.mode===1?norm(raw).replace(/\s/g,'')===norm(target):norm(raw)===norm(target);s.answers.push({word:w,raw,ok});s.checked=true;if(boxed)cells.forEach(c=>{c.readOnly=true;c.classList.add(ok?'correct':'incorrect')});else $('#answer').readOnly=true;$('#feedback').innerHTML=`<div class="feedback ${ok?'':'wrong'}"><strong>${ok?'✓ 정답이에요!':'다시 기억해 두세요'}</strong><br>${esc(w.en)} · ${esc(w.ko)}${pronunciationHTML(w.en)}</div>`;hydratePronunciations($('#feedback'));$('#check').textContent=s.index===s.questions.length-1?'결과 보기 →':'다음 문제 →';$('#check').focus();};}
function result(){const s=session,score=s.answers.filter(a=>a.ok).length;if(!s.saved){history.unshift({date:new Date().toISOString(),mode:s.mode,score,total:s.questions.length});history=history.slice(0,100);persist();s.saved=true}app.innerHTML=`<div class="test"><div class="center"><div class="eyebrow">A LITTLE MORE GROWN</div><h2>오늘도 한 뼘 자랐어요</h2><div class="score">${Math.round(score/s.questions.length*100)}<span class="muted">점</span></div><p class="muted">${s.questions.length}문항 중 ${score}문항 정답 · ${titles[s.mode]}</p></div>${s.answers.map(a=>`<div class="review">${a.ok?'✓':'○'} <strong>${esc(a.word.en)}</strong> · ${esc(a.word.ko)}${pronunciationHTML(a.word.en)}<small>내 답: ${esc(a.raw)} · ${a.ok?'정답':'오답'}</small></div>`).join('')}<div class="actions" style="margin-top:25px"><button class="primary" id="again">다시 연습하기 →</button></div></div>`;hydratePronunciations(app);$('#again').onclick=()=>{session=null;quiz()};}
function records(){app.innerHTML=`<div class="section-head"><div><div class="eyebrow">YOUR GROWTH JOURNAL</div><h1>차곡차곡 쌓인 연습</h1><p class="muted">최근 100회의 테스트 기록을 이 브라우저에 보관해요.</p></div></div><div class="test" style="margin:25px 0;max-width:100%">${history.length?history.map(h=>`<div class="review"><strong>${titles[h.mode]}</strong> <span style="float:right">${h.score} / ${h.total} 정답 · ${Math.round(h.score/h.total*100)}점</span><small>${new Date(h.date).toLocaleString('ko-KR')}</small></div>`).join(''):'<div class="empty">첫 번째 테스트를 마치면 학습 기록이 생겨요.</div>'}</div>${footer()}`;}
render();
